import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { categorySlug } from './category-slug';

/**
 * The slug rule, proved against the approved category tree itself.
 *
 * WHY THIS TEST READS A FILE FROM ANOTHER WORKSPACE. The approved 164 slugs
 * live in apps/customer-web/src/lib/businesses/category-tree.ts, generated by
 * scripts/gen-categories.cjs. The point of `categorySlug` is to agree with
 * that file for every one of those 164 names, so the honest way to test it is
 * to read the file and compare — not to copy 164 names into this spec, where
 * a typo would make the test agree with itself and nothing else.
 *
 * It is a plain fs read, not an import: apps/api gains no module dependency on
 * apps/customer-web, no build coupling and no shared tsconfig path. If the
 * tree file is ever moved or renamed, this test fails loudly with a message
 * saying so, which is the correct outcome — it means the source of truth moved
 * and the rule's proof needs re-pointing, not that the rule is wrong.
 */

const TREE = join(
  __dirname,
  '../../../../customer-web/src/lib/businesses/category-tree.ts'
);

/** Every (name, slug) pair the approved tree declares, in file order. */
function approvedPairs(): Array<{ name: string; slug: string }> {
  let source: string;
  try {
    source = readFileSync(TREE, 'utf8');
  } catch {
    throw new Error(
      `The approved category tree was not found at ${TREE}. ` +
        'This test proves categorySlug() against that file; if the file has ' +
        'moved, update TREE in category-slug.spec.ts rather than deleting ' +
        'this test.'
    );
  }

  // Each entry declares `slug: '...'` then `name: "..."`, on one line for a
  // subcategory and across two for a main category — hence the tolerant gap.
  // Names are double-quoted in the generated file and slugs single-quoted.
  const pattern = /slug:\s*'([^']+)',\s*name:\s*"([^"]+)"/g;
  const pairs: Array<{ name: string; slug: string }> = [];
  for (const match of source.matchAll(pattern)) {
    pairs.push({ slug: match[1]!, name: match[2]! });
  }
  return pairs;
}

describe('categorySlug', () => {
  const pairs = approvedPairs();

  it('finds all 164 approved category entries in the tree', () => {
    // Guards the regex itself: if the generated file's formatting ever
    // changes, this fails rather than silently asserting over 3 pairs.
    expect(pairs).toHaveLength(164);
  });

  it('reproduces the slug of every approved category exactly', () => {
    const wrong = pairs
      .filter((p) => categorySlug(p.name) !== p.slug)
      .map((p) => `${p.name} -> ${categorySlug(p.name)} (tree says ${p.slug})`);

    expect(wrong).toEqual([]);
  });

  // The transformations, named one at a time, so a failure says which rule
  // broke rather than only that some name came out wrong.
  it('lowercases', () => {
    expect(categorySlug('Bakery')).toBe('bakery');
  });

  it('turns & into the word "and", with separators on both sides', () => {
    expect(categorySlug('Oil & Ghee')).toBe('oil-and-ghee');
    expect(categorySlug('Salt, Sugar & Spices')).toBe('salt-sugar-and-spices');
  });

  it('treats / as a separator, not a deletion', () => {
    expect(categorySlug('Rava/Sooji')).toBe('rava-sooji');
  });

  it('collapses a comma and its following space into one hyphen', () => {
    expect(categorySlug('Rice, Atta & Flour')).toBe('rice-atta-and-flour');
  });

  it('collapses any run of separators into a single hyphen', () => {
    expect(categorySlug('Ready  --  to   Eat')).toBe('ready-to-eat');
  });

  it('trims leading and trailing hyphens', () => {
    expect(categorySlug('  Bakery  ')).toBe('bakery');
    expect(categorySlug('& Bakery &')).toBe('and-bakery-and');
  });

  it('keeps digits', () => {
    expect(categorySlug('Atta 5 kg')).toBe('atta-5-kg');
  });

  it('leaves an already-valid slug unchanged', () => {
    expect(categorySlug('rice-atta-and-flour')).toBe('rice-atta-and-flour');
  });

  it('drops characters that have no place in a slug', () => {
    expect(categorySlug("Chef's Choice (New!)")).toBe('chef-s-choice-new');
  });

  // A name with nothing slug-able returns '', which callers must reject —
  // migration 0061's format CHECK refuses it too.
  it('returns an empty string when a name has no slug-able characters', () => {
    expect(categorySlug('')).toBe('');
    expect(categorySlug('   ')).toBe('');
    expect(categorySlug('!!!')).toBe('');
  });

  it('is idempotent: slugging a slug changes nothing', () => {
    for (const p of pairs) {
      expect(categorySlug(p.slug)).toBe(p.slug);
    }
  });

  it('produces a slug that satisfies the 0061 format constraint', () => {
    const shape = /^[a-z0-9]+(-[a-z0-9]+)*$/;
    for (const p of pairs) {
      expect(categorySlug(p.name)).toMatch(shape);
    }
  });
});
